import java.math.*;
public class C {
  static MathContext MC = MathContext.DECIMAL64;
  static BigDecimal price(BigDecimal t, int n){
    BigDecimal i = new BigDecimal("0.0199");
    BigDecimal f = BigDecimal.ONE.add(i).pow(n, MC);
    BigDecimal d = BigDecimal.ONE.subtract(BigDecimal.ONE.divide(f, MC));
    return t.multiply(i).divide(d, MC);
  }
  public static void main(String[] a){
    for(int n : new int[]{4,6,12}){
      BigDecimal t = new BigDecimal("413.80");
      BigDecimal p = price(t,n).setScale(2, RoundingMode.HALF_EVEN);
      System.out.println(n+"x total 413.80 -> parcela "+p+" totalFinal "+p.multiply(BigDecimal.valueOf(n)).setScale(2,RoundingMode.HALF_EVEN)+" ajuste "+p.multiply(BigDecimal.valueOf(n)).subtract(t).setScale(2,RoundingMode.HALF_EVEN));
    }
    BigDecimal t2 = new BigDecimal("431.45");
    BigDecimal p2 = price(t2,6).setScale(2, RoundingMode.HALF_EVEN);
    System.out.println("ex2 6x: "+p2+" total "+p2.multiply(BigDecimal.valueOf(6)));
  }
}
